pub fn score(batches: &[Vec<&str>]) -> i32 {
    let mut result = 0;
    for batch in batches {
        for name in batch {
            let count = recipe::portions(name);
            if count > 0 && count <= 3 {
                result += count;
            }
        }
    }
    result
}

