pub fn reserve(&mut self, name: &str) -> bool {
        let dose = recipe::portions(name);
        if dose == 0 || self.remaining(name) < dose {
            return false;
        }
        *self.beans.entry(name.to_string()).or_default() -= dose;
        true
    }

